// json_util 实现：编码转换、JSON 解析/序列化与参数读取
#include "utils/json_util.h" // 自身声明
#include <cstdlib> // atoi
#include "include/cef_parser.h" // CefParseJSON/CefWriteJSON
std::wstring Utf8ToWide(const std::string& text) { if (text.empty()) return std::wstring(); const int length = ::MultiByteToWideChar(CP_UTF8, 0, text.data(), static_cast<int>(text.size()), nullptr, 0); std::wstring result(static_cast<size_t>(length), L'\0'); ::MultiByteToWideChar(CP_UTF8, 0, text.data(), static_cast<int>(text.size()), &result[0], length); return result; } // UTF-8 → UTF-16：先算长度再转换
std::string WideToUtf8(const std::wstring& text) { if (text.empty()) return std::string(); const int length = ::WideCharToMultiByte(CP_UTF8, 0, text.data(), static_cast<int>(text.size()), nullptr, 0, nullptr, nullptr); std::string result(static_cast<size_t>(length), '\0'); ::WideCharToMultiByte(CP_UTF8, 0, text.data(), static_cast<int>(text.size()), &result[0], length, nullptr, nullptr); return result; } // UTF-16 → UTF-8：先算长度再转换
CefRefPtr<CefDictionaryValue> ParseJsonObject(const std::string& utf8) { CefRefPtr<CefValue> value = CefParseJSON(utf8, JSON_PARSER_RFC); if (value == nullptr || value->GetType() != VTYPE_DICTIONARY) return nullptr; return value->GetDictionary(); } // 解析 JSON 并要求根为字典
std::string WriteJson(CefRefPtr<CefValue> value) { if (value == nullptr) return std::string(); return CefWriteJSON(value, JSON_WRITER_DEFAULT).ToString(); } // CefValue → UTF-8 JSON 文本
CefRefPtr<CefValue> StringValue(const std::string& utf8) { CefRefPtr<CefValue> value = CefValue::Create(); value->SetString(utf8); return value; } // 字符串包装为 CefValue
CefRefPtr<CefValue> DictValue(CefRefPtr<CefDictionaryValue> dict) { if (dict == nullptr) return nullptr; CefRefPtr<CefValue> value = CefValue::Create(); value->SetDictionary(dict); return value; } // 字典包装为 CefValue（与 CefValue 无继承关系，必须套一层）
CefRefPtr<CefValue> ListValue(CefRefPtr<CefListValue> list) { if (list == nullptr) return nullptr; CefRefPtr<CefValue> value = CefValue::Create(); value->SetList(list); return value; } // 列表包装为 CefValue
std::string WriteJsonDict(CefRefPtr<CefDictionaryValue> dict) { return WriteJson(DictValue(dict)); } // 字典 → JSON 文本
std::string WriteJsonList(CefRefPtr<CefListValue> list) { return WriteJson(ListValue(list)); } // 列表 → JSON 文本
static CefRefPtr<CefValue> ArgOf(CefRefPtr<CefDictionaryValue> args, const std::string& key) { if (args == nullptr || !args->HasKey(key)) return nullptr; return args->GetValue(key); } // 取参数原始 CefValue，缺失返回 nullptr
bool ArgGetString(CefRefPtr<CefDictionaryValue> args, const std::string& key, std::string& out) { CefRefPtr<CefValue> value = ArgOf(args, key); if (value == nullptr || value->GetType() != VTYPE_STRING) return false; out = value->GetString().ToString(); return true; } // 读字符串参数
bool ArgGetInt(CefRefPtr<CefDictionaryValue> args, const std::string& key, int& out) { CefRefPtr<CefValue> value = ArgOf(args, key); if (value == nullptr) return false; if (value->GetType() == VTYPE_INT) { out = value->GetInt(); return true; } if (value->GetType() == VTYPE_STRING) { const std::string text = value->GetString().ToString(); out = std::atoi(text.c_str()); return true; } return false; } // 读整型参数：整型直取，字符串尝试 atoi
bool ArgGetDouble(CefRefPtr<CefDictionaryValue> args, const std::string& key, double& out) { CefRefPtr<CefValue> value = ArgOf(args, key); if (value == nullptr || (value->GetType() != VTYPE_DOUBLE && value->GetType() != VTYPE_INT)) return false; out = value->GetType() == VTYPE_INT ? static_cast<double>(value->GetInt()) : value->GetDouble(); return true; } // 读浮点参数：兼容整型
bool ArgGetBool(CefRefPtr<CefDictionaryValue> args, const std::string& key, bool& out) { CefRefPtr<CefValue> value = ArgOf(args, key); if (value == nullptr) return false; switch (value->GetType()) { case VTYPE_BOOL: out = value->GetBool(); return true; case VTYPE_INT: out = value->GetInt() != 0; return true; case VTYPE_STRING: out = value->GetString().ToString() == "true"; return true; default: return false; } } // 读布尔参数：兼容整型与 "true" 字符串
CefRefPtr<CefListValue> ArgGetList(CefRefPtr<CefDictionaryValue> args, const std::string& key) { CefRefPtr<CefValue> value = ArgOf(args, key); if (value == nullptr || value->GetType() != VTYPE_LIST) return nullptr; return value->GetList(); } // 读列表参数
CefRefPtr<CefDictionaryValue> ArgGetDict(CefRefPtr<CefDictionaryValue> args, const std::string& key) { CefRefPtr<CefValue> value = ArgOf(args, key); if (value == nullptr || value->GetType() != VTYPE_DICTIONARY) return nullptr; return value->GetDictionary(); } // 读字典参数
CefRefPtr<CefDictionaryValue> MakeDict() { return CefDictionaryValue::Create(); } // 新建空字典
CefRefPtr<CefListValue> MakeList() { return CefListValue::Create(); } // 新建空列表
void ListAddString(CefRefPtr<CefListValue> list, const std::string& value) { if (list != nullptr) list->SetString(list->GetSize(), value); } // 列表尾部追加字符串
void ListAddDict(CefRefPtr<CefListValue> list, CefRefPtr<CefDictionaryValue> value) { if (list != nullptr) list->SetValue(list->GetSize(), DictValue(value)); } // 列表尾部追加字典
std::string StrOf(CefRefPtr<CefDictionaryValue> dict, const std::string& key) { std::string out; ArgGetString(dict, key, out); return out; } // 取字符串值（缺失回空串）
int IntOf(CefRefPtr<CefDictionaryValue> dict, const std::string& key) { int out = 0; ArgGetInt(dict, key, out); return out; } // 取整型值（缺失回 0）
bool BoolOf(CefRefPtr<CefDictionaryValue> dict, const std::string& key) { bool out = false; ArgGetBool(dict, key, out); return out; } // 取布尔值（缺失回 false）
std::string Utf8Slice(const std::string& text, size_t start, size_t max_bytes, size_t& next) { if (start >= text.size()) { next = text.size(); return std::string(); } size_t end = start + max_bytes; if (end > text.size()) end = text.size(); while (end > start && end < text.size() && (static_cast<unsigned char>(text[end]) & 0xC0) == 0x80) --end; if (end == start) { end = start + 1; while (end < text.size() && (static_cast<unsigned char>(text[end]) & 0xC0) == 0x80) ++end; } // 回退到 UTF-8 字符边界：显式检查 end < text.size()
    next = end; return text.substr(start, end - start); } // 按 UTF-8 边界切片并回写下一片段起始下标
